import {Locale} from '@/model/content/Locale'
import {ui as enUi} from '@/model/content/locales/en/ui'
import {seo as enSeo} from '@/model/content/locales/en/seo'
import {
  generatedLocaleCatalog,
  generatedLocaleMetadataFor
} from '@/model/content/translation/GeneratedLocaleCatalogs'
import type {Locale as LocaleCode, SeoContent, UiContent} from '@/model/content/Schema'
import {CatalogTranslationResolver} from '@/model/content/translation/TranslationResolver'
import {translateSeoContent, translateUiContent} from '@/model/content/translation/StaticContentTranslation'

/** Open Graph locale of any language, including alternates whose catalog is never loaded. */
export function ogLocaleFor(locale: LocaleCode): string {
  return generatedLocaleMetadataFor(locale)?.ogLocale || enSeo.ogLocale
}

let ui: UiContent | undefined
let seo: SeoContent | undefined

// English source content until the active locale's translations are loaded, and
// the translated content for the rest of the page life once they are. Only the
// translated result is cached, so a read before the catalog arrives cannot pin
// the page to English.
export function activeUi(): UiContent {
  if (ui) return ui
  const catalog = generatedLocaleCatalog(Locale.active)
  if (!catalog) return enUi
  return ui = translateUiContent(enUi, new CatalogTranslationResolver(catalog))
}

export function activeSeo(): SeoContent {
  if (seo) return seo
  const catalog = generatedLocaleCatalog(Locale.active)
  if (!catalog) return enSeo
  return seo = {
    ...translateSeoContent(enSeo, new CatalogTranslationResolver(catalog)),
    ogLocale: catalog.ogLocale
  }
}
