import {englishCVContent} from '@/model/Data/CVData'
import {englishTechnologyProfileContent} from '@/model/Data/TechnologyProfileData'
import {generatedLocaleCatalog} from '@/model/content/translation/GeneratedLocaleCatalogs'
import {englishContent} from '@/model/content/locales/en'
import type {Locale, LocalizedContent} from '@/model/content/Schema'
import {
  translateCVContent,
  translateTechnologyProfileContent,
  translateProfile,
  translateProjects,
  translateSolutions
} from '@/model/content/translation/ModelContentTranslation'
import {CatalogTranslationResolver} from '@/model/content/translation/TranslationResolver'
import {
  translateSeoContent,
  translateUiContent
} from '@/model/content/translation/StaticContentTranslation'

export function generatedLocalizedContent(locale: Locale): LocalizedContent | undefined {
  const catalog = generatedLocaleCatalog(locale)
  if (!catalog) return undefined
  const resolver = new CatalogTranslationResolver(catalog)
  return {
    locale,
    status: 'final',
    ui: translateUiContent(englishContent.ui, resolver),
    seo: {
      ...translateSeoContent(englishContent.seo, resolver),
      ogLocale: catalog.ogLocale
    },
    projects: data => translateProjects(data, resolver),
    profile: data => translateProfile(data, resolver),
    solutions: data => translateSolutions(data, resolver),
    cv: data => data.setLocalizedContent(translateCVContent(englishCVContent, resolver)),
    technologyProfile: data => data.setLocalizedContent(translateTechnologyProfileContent(englishTechnologyProfileContent, resolver))
  }
}
