import Vue from 'vue'
import Router, {RouteConfig} from 'vue-router'
import Routes from '@/model/Routes'
import {Locale, normalizeBareLocale, preferredLocaleRedirect, routerBase} from '@/model/content/Locale'
import {projectCatalog} from '@/model/content/catalog/projects'

Vue.use(Router)

if (typeof window !== 'undefined') {
  const normalizedPath = normalizeBareLocale(window.location.pathname)
  const preferredPath = preferredLocaleRedirect()
  if (preferredPath) window.location.replace(preferredPath)
  else if (normalizedPath !== window.location.pathname) {
    window.history.replaceState(window.history.state, '', `${normalizedPath}${window.location.search}${window.location.hash}`)
  }
}

const Portal = () => import(/* webpackChunkName: "portal" */ '@/view/Portal.vue')
const Gateway = () => import(/* webpackChunkName: "gateway" */ '@/view/Gateway.vue')
const Introduction = () => import(/* webpackChunkName: "introduction" */ '@/view/Introduction/Introduction.vue')
const Solutions = () => import(/* webpackChunkName: "solutions" */ '@/view/Solutions/Solutions.vue')
const Projects = () => import(/* webpackChunkName: "projects" */ '@/view/CaseStudies/CaseStudies.vue')
const ProjectDetail = () => import(/* webpackChunkName: "project-detail" */ '@/view/CaseStudies/CaseStudyDetail.vue')
const Experience = () => import(/* webpackChunkName: "experience" */ '@/view/Experience/Experience.vue')
const CV = () => import(/* webpackChunkName: "cv" */ '@/view/CV/CV.vue')
const PrintableCV = () => import(/* webpackChunkName: "printable-cv" */ '@/view/CV/PrintableCV.vue')
const PrintableTechnologies = () => import(/* webpackChunkName: "printable-technologies" */ '@/view/CV/PrintableTechnologies.vue')
const Contact = () => import(/* webpackChunkName: "contact" */ '@/view/Contact/Contact.vue')
const FAQ = () => import(/* webpackChunkName: "faq" */ '@/view/FAQ/FAQ.vue')

const legacyProjectRedirectRoutes: RouteConfig[] = projectCatalog
  .map(project => (project.lineage?.mergedLegacyRoutes || []).map(legacyRoute => ({
    path: `projects/${legacyRoute}`,
    redirect: {name: Routes.project, params: {projectRoute: project.route}}
  })))
  .reduce<RouteConfig[]>((all, routes) => all.concat(routes), [])

const legacyRootRedirectRoutes: RouteConfig[] = [
  {path: '/solutions', redirect: {name: Routes.solutions}},
  {path: '/experience', redirect: {name: Routes.experience}},
  {path: '/cv', redirect: {name: Routes.cv}},
  {path: '/cv/print', redirect: {name: Routes.cvPrint}},
  {path: '/contact', redirect: {name: Routes.contact}}
]

const router = new Router({
  mode: 'history',
  base: routerBase(Locale.active),
  scrollBehavior: () => ({x: 0, y: 0}),
  routes: [
    {path: Routes.gatewayPath, name: Routes.gateway, component: Gateway},
    {path: Routes.cvPrintPath, name: Routes.cvPrint, component: PrintableCV},
    {path: Routes.technologiesPrintPath, name: Routes.technologiesPrint, component: PrintableTechnologies},
    {
      path: Routes.servicesPath,
      component: Portal,
      children: [
        {
          path: '',
          redirect: {name: Routes.introduction}
        },
        {
          path: 'introduction',
          name: Routes.introduction,
          component: Introduction
        },
        {
          path: 'solutions',
          name: Routes.solutions,
          component: Solutions
        },
        {
          path: 'experience',
          name: Routes.experience,
          component: Experience
        },
        {
          path: 'cv',
          name: Routes.cv,
          component: CV
        },
        {
          path: 'contact',
          name: Routes.contact,
          component: Contact
        },
        {
          path: 'projects',
          name: Routes.projects,
          component: Projects
        },
        ...legacyProjectRedirectRoutes,
        {
          path: 'projects/:projectRoute',
          name: Routes.project,
          component: ProjectDetail,
          props: true
        }
      ]
    },
    ...legacyRootRedirectRoutes,
    {
      path: Routes.faqPath,
      component: Portal,
      children: [
        {
          path: '',
          name: Routes.faq,
          component: FAQ
        }
      ]
    },
    {
      path: '*',
      redirect: {name: Routes.gateway}
    }
  ]
})
export default router
