import Vue from 'vue'
import Vuetify from 'vuetify'
import 'vuetify/dist/vuetify.min.css'

// Keep in sync with --primary-color in styles.styl: Vuetify generates its
// `primary` palette classes from this value, so leaving it at the library
// default would give `color="primary"` elements a different blue than the
// design tokens.
Vue.use(Vuetify, {
  iconfont: 'md',
  theme: {
    primary: '#306fdb'
  }
})
