export interface ProfileSocialLinkData {
  icon: string
  title: string
  url: string
}

export const ProfileContactIds = {
  email: 'email',
  whatsapp: 'whatsapp',
  slovakPhone: 'slovak-phone'
} as const

export type ProfileContactId = typeof ProfileContactIds[keyof typeof ProfileContactIds]

export interface ProfileContactLinkData extends ProfileSocialLinkData {
  id: ProfileContactId
  label?: string
  value: string
}

function profileContact(
  id: ProfileContactId,
  icon: string,
  value: string,
  url: string,
  label?: string
): ProfileContactLinkData {
  return {id, icon, label, value, title: label ? `${label} · ${value}` : value, url}
}

export interface EducationEntry {
  school: string
  degree: string
  startDate: PartialDate
  endDate?: PartialDate
}

export interface EducationDisplay {
  school: string
  degree: string
  date: string
}

export interface ExperienceRelatedProject {
  route: ProjectRoute
  title: string
}

/** Experience catalog and localized content joined into one renderable entry. */
export interface ExperienceItem {
  id: ExperienceId
  client: string
  clientUrl?: string
  position: string
  title: string
  summary?: string
  highlights: ExperienceHighlight[]
  technologies: string[]
  relatedProjects: ExperienceRelatedProject[]
  date: string
  startYear: number
  endYear?: number
  isCurrent: boolean
}

