  constructor(
    private projects: ProjectsData,
    private locale: Locale = 'en'
  ) {
  }

  setLocalizedExperience(content: Record<ExperienceId, ExperienceContent>) {
    this.experienceContent = content
  }

  setLocalizedEducation(entries: EducationEntry[]) {
    this.educationEntries = entries
  }

  get translatableExperienceContent(): Readonly<Record<ExperienceId, ExperienceContent>> {
    return this.experienceContent
  }

  get translatableEducationEntries(): readonly EducationEntry[] {
    return this.educationEntries
  }

  contact(id: ProfileContactId): ProfileContactLinkData {
    const contact = this.contactLinks.find(item => item.id === id)
    if (!contact) throw new Error(`Missing profile contact: ${id}`)
    return contact
  }

  get activityDates(): string {
    return `${this.careerStartYear} – ${activeUi().present}`
  }

  get fullCareerDates(): string {
    const firstYear = Math.min(...experienceCatalog.map(entry => entry.startDate.year))
    return `${firstYear} – ${activeUi().present}`
  }

  get experience(): ExperienceItem[] {
    return experienceCatalog.map(entry => {
      const content = this.experienceContent[entry.id]
      return {
        id: entry.id,
        client: content.client,
        clientUrl: entry.clientUrl,
        position: content.position,
        title: content.title,
        summary: content.summary,
        highlights: content.highlights,
        technologies: content.technologies,
        relatedProjects: entry.relatedProjectRoutes.map(route => ({
          route,
          title: this.relatedProjectTitle(route)
        })),
        date: formatDateRange(entry.startDate, entry.endDate, entry.isCurrent, this.locale, {presentLabel: activeUi().present}),
        startYear: entry.startDate.year,
        endYear: entry.endDate?.year,
        isCurrent: Boolean(entry.isCurrent)
      }
    })
  }

  get education(): EducationDisplay[] {
    return this.educationEntries.map(entry => ({
      school: entry.school,
      degree: entry.degree,
      date: formatDateRange(entry.startDate, entry.endDate, false, this.locale, {presentLabel: activeUi().present})
    }))
  }

  private relatedProjectTitle(route: ProjectRoute) {
    return this.projects.require(route).title
  }
