export type TechnologyLevel = 'familiar' | 'working' | 'advanced' | 'expert'
export type TechnologyCategory = 'languages' | 'mobile' | 'audio' | 'web' | 'cloud' | 'ai' | 'quality' | 'foundations'

export interface TechnologyEntry {
  id: string
  name: string
  category: TechnologyCategory
  level: TechnologyLevel
  years: number
  description: string
}

function technology(
  id: string, name: string, category: TechnologyCategory, level: TechnologyLevel,
  years: number, description: string
): TechnologyEntry {
  return {id, name, category, level, years, description}
}

