export class TechnologyProfileData {
  private content = englishTechnologyProfileContent
  readonly updatedDate = '2026-11-02'
  readonly downloadUrl: string
  readonly downloadName: string

  constructor(private locale: Locale) {
    this.downloadUrl = `${Routes.cvPath}/rene-dohan-technologies-${locale}.pdf`
    this.downloadName = `Rene-Dohan-Technologies-${locale.toUpperCase()}.pdf`
  }

  setLocalizedContent(content: TechnologyProfileContent) {
    this.content = content
    return this
  }

  get copy() { return this.content }

  get updatedOn() {
    return new Intl.DateTimeFormat(this.locale, {year: 'numeric', month: 'long', day: 'numeric', timeZone: 'UTC'})
      .format(new Date(`${this.updatedDate}T00:00:00Z`))
  }

  get groups() {
    return (Object.keys(this.content.categories) as TechnologyCategory[]).map(id => ({
      id,
      title: this.content.categories[id],
      entries: technologyCatalog.filter(entry => entry.category === id).map(entry => ({
        ...entry,
        description: this.content.descriptions[entry.id],
        levelLabel: this.content.levels[entry.level].label,
        yearsLabel: String(entry.years)
      }))
    }))
  }
}
